/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Track changes related to Auto Charges and add entry to Price Change tracking table 
/// </summary>
using System.ComponentModel.Composition;

[Export(identifierStr(Dynamics.AX.Application.METPriceChangeEvent))]
[ExportMetadata(enumStr(METPriceChangeType), enumLiteralStr(METPriceChangeType, AutoChargeDisabled))]
public class METPriceChangeEventAutoChargeDisabled extends METPriceChangeEvent
{
    MarkupAutoTable         markupAutoTable;
    RecordInsertList        priceChangeTrackingDetailList;
    LineNumber              lineNumber;

}

Method.Source:
/// <summary>
/// Initialise the instance
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void initInstance(Common _common, SysAppCRUDOperation _crud)
{
    this.setInternals(_Common, _crud);
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void setInternals(Common _common, SysAppCRUDOperation _crud)
{
    super(_common, _crud);
    markupAutoTable = _common as MarkupAutoTable;
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeType()
{
    return METPriceChangeType::AutoChargeDisabled;
}

/// <summary>
/// Process the base record that triggered the change and create Price Change Track record
/// </summary>
public void process()
{
    if(markupAutoTable.ModuleCategory == HeadingLine::Heading)
    {
        this.processHeaderCharge();
    }
    else if(markupAutoTable.ModuleCategory == HeadingLine::Line)
    {
        this.processLineCharge();
    }
}

    /// <summary>
    /// Process the base record of Header Charge type
    /// </summary>
    public void processHeaderCharge()
    {
        MarkupAutoLine  markupAutoLine;

        while select markupAutoLine
            where   markupAutoLine.TableRecId       == markupAutoTable.recid
            &&      markupAutoLine.TableTableId     == markupAutoTable.TableId
            &&     (markupAutoLine.MarkupCategory   == MarkupCategory::Percent || markupAutoLine.MarkupCategory   == MarkupCategory::Pcs)
            &&      markupAutoLine.InventSiteId
        {
            this.processSimple(markupAutoLine);
        }
    }

    /// <summary>
    /// Process the base record of Line Charge type
    /// </summary>
    public void processLineCharge()
    {
        MarkupAutoLine  markupAutoLine;

        while select markupAutoLine
            where   markupAutoLine.TableRecId       == markupAutoTable.recid
            &&      markupAutoLine.TableTableId     == markupAutoTable.TableId
            &&      markupAutoLine.InventSiteId
        {
            this.processSimple(markupAutoLine);
        }
    }

    /// <summary>
    /// Process the base record that triggered the change and create Price Change Track record
    /// </summary>
    /// <param name = "_markupAutoLine">Auto charge line</param>
    public void processSimple(MarkupAutoLine  _markupAutoLine)
    {
        FromDate                    fromDate;
        RetailQtyLowest             fromQty;
        boolean                     skipCreation;
        Counter                     insertCount;

        fromDate = this.getFromDate(_markupAutoLine.FromDate);
        fromQty = this.getFromQty(_markupAutoLine.FromAmount);

        this.cleanup(fromDate, fromQty, _markupAutoLine);

        //85562, Price components when disabled are not populating Price change tracking details table as expected (Table 1.1) -->
        //skipCreation = this.preProcess(fromDate, fromQty, sourceCrud, _markupAutoLine);

        //if(!SkipCreation)
        //85562, Price components when disabled are not populating Price change tracking details table as expected (Table 1.1) <--
        //{
        ttsbegin;

        this.processTrans(fromDate, fromQty, _markupAutoLine);
        priceChangeTracking.insert();
            
        ttscommit;

        ttsbegin;

        priceChangeTrackingDetailList = new RecordInsertList(tableNum(METPriceChangeTrackingDetail));
        this.processDetail(_markupAutoLine);
        insertCount = priceChangeTrackingDetailList.insertDatabase();

        if(!insertCount) //no detail record was created
        {
            priceChangeTracking.selectForUpdate(true);
            priceChangeTracking.delete();
        }

        ttscommit;

        //}
    }

/// <summary>
/// Process the base record that triggered the change and create Price Change Track record
/// </summary>
/// <param name = "_fromDate">From Date</param>
/// <param name = "_fromQty">From Quantity</param>
/// <param name = "_markupAutoLine">Markup line record</param>
public void processTrans(FromDate _fromDate, RetailQtyLowest _fromQty, MarkupAutoLine  _markupAutoLine)
{
    priceChangeTracking.clear();
    this.setCommonValues(_markupAutoLine);
    priceChangeTracking.ChargeCodeDescription   = markupAutoTable.Description;
    priceChangeTracking.ChargeCodeLineNum       = _markupAutoLine.lineNum;
    priceChangeTracking.PriceComponentCode      = markupAutoTable.PriceComponentCodeName;
    priceChangeTracking.PricingRuleHeader       = _markupAutoLine.pricingRuleHeader ? _markupAutoLine.pricingRuleHeader : markupAutoTable.PricingRuleHeader;
    priceChangeTracking.PricingRuleLine         = _markupAutoLine.PricingRuleLine ? _markupAutoLine.PricingRuleLine : markupAutoTable.PricingRuleLine;
    priceChangeTracking.Activation              = NoYes::No;
    priceChangeTracking.QuantityAmountFrom      = _fromQty;
    priceChangeTracking.FromDate                = _fromDate;
    priceChangeTracking.ChargeCodeModuleCategory = markupAutoTable.ModuleCategory;
}

    /// <summary>
    /// Create detail records related to the base record that triggered the change. Specific to Disabled scenario.
    /// </summary>
    /// <param name = "_markupAutoLine">Markup line record</param>
    public void processDetail(MarkupAutoLine  _markupAutoLine)
    {
        Query                       custPreviewQuery;
        Query                       productPreviewQuery;
        GUPPricingRuleCopy          pricingRuleCopyCustHeader, pricingRuleCopy;
        Set                         custAccountSet, inventItemSet;
        str                         message;

        METPriceChangeTrack priceChangeTrack = METPriceChangeTrackFactory::newFromPriceChangeType(priceChangeTracking.ChangeType);
        priceChangeTrack.initInstance(priceChangeTracking, false);

        pricingRuleCopyCustHeader.initFromPricingRule(GUPPricingRule::find(priceChangeTracking.pricingRuleHeader));
        
        pricingRuleCopy.initFromPricingRule(GUPPricingRule::find(priceChangeTracking.pricingRuleLine));
        
        custPreviewQuery = priceChangeTrack.buildCustQuery(pricingRuleCopyCustHeader, _markupAutoLine.inventSiteId, markupAutoTable.PricingGroupCodeHeader);
        custAccountSet = priceChangeTrack.buildCustValues(custPreviewQuery, pricingRuleCopyCustHeader);
         
        if(custAccountSet)
        {
            productPreviewQuery = priceChangeTrack.buildProductQueryBase(pricingRuleCopy);
            inventItemSet = priceChangeTrack.buildItemValues(productPreviewQuery, pricingRuleCopy);

            if(inventItemSet)
            {
                this.processDetailQuantity(custAccountSet, inventItemSet, _markupAutoLine);
            }
            
        }
    }

    /// <summary>
    /// Create detail records related to the base record that triggered the change. Specific to Disabled scenario.
    /// </summary>
    /// <param name = "_custAccountSet">Customer Accounts</param>
    /// <param name = "_inventItemSet">Items</param>
    /// <param name = "_markupAutoLine">Markup line record</param>
    public void processDetailQuantity(Set _custAccountSet, Set _inventItemSet, MarkupAutoLine  _markupAutoLine)
    {
        SetEnumerator       custAccountEnumerator, inventItemEnumerator;
        AccountNum          custAccount;
        ItemId              inventItem;

        if(_custAccountSet && _inventItemSet)
        {
            custAccountEnumerator = _custAccountSet.getEnumerator();
            while(custAccountEnumerator.moveNext())
            {
                custAccount = custAccountEnumerator.current();
                this.processDetailTrans(METPriceTrackDetailType::Customer, custAccount, _markupAutoLine.LineNum);
            }

            inventItemEnumerator = _inventItemSet.getEnumerator();
            while(inventItemEnumerator.moveNext())
            {
                inventItem  = inventItemEnumerator.current();
                this.processDetailTrans(METPriceTrackDetailType::Product, inventItem, _markupAutoLine.LineNum);
            }

            if(_markupAutoLine.inventSiteId)
            {
                this.processDetailTrans(METPriceTrackDetailType::SiteId, _markupAutoLine.inventSiteId, _markupAutoLine.LineNum);
            }
        }
    }

    /// <summary>
    /// Create detail records related to the base record that triggered the change. Specific to Disabled scenario.
    /// </summary>
    /// <param name = "_priceTrackDetailType">Price change type</param>
    /// <param name = "_priceTrackDetailCode">Price change code</param>
    /// <param name = "_lineNumber">Line number</param>
    public void processDetailTrans(METPriceTrackDetailType _priceTrackDetailType, METPriceTrackDetailCode _priceTrackDetailCode, LineNumber _lineNumber)
    {
        METPriceChangeTrackingDetail    priceChangeTrackingDetail;

        priceChangeTrackingDetail.clear();
        priceChangeTrackingDetail.initValue();
        priceChangeTrackingDetail.TrackingId        = priceChangeTracking.TrackingId;
        priceChangeTrackingDetail.ChangeType        = priceChangeTracking.ChangeType;
        priceChangeTrackingDetail.LineNumber          = _lineNumber;
        priceChangeTrackingDetail.PriceTrackDetailType = _priceTrackDetailType;
        priceChangeTrackingDetail.PriceTrackDetailCode = _priceTrackDetailCode;

        priceChangeTrackingDetailList.add(priceChangeTrackingDetail);
    }

    /// <summary>
    /// Pre Process logic
    /// In some scenarios we may delete an existing record and not create the current one.
    /// </summary>
    /// <param name = "_fromDate">from date</param>
    /// <param name = "_fromQty">qty from</param>
    /// <param name = "_crud">CRUD operation</param>
    /// <param name = "_markupAutoLine">Auto charge line</param>
    /// <returns>Success</returns>
    public boolean preProcess(FromDate _fromDate, RetailQtyLowest _fromQty, SysAppCRUDOperation _crud, MarkupAutoLine _markupAutoLine)
    {
        boolean ret = false;
        METPriceChangeTracking      priceChangeTrackingLoc;

        //As this is a Disabled action, remove any existing Enabled
        ttsbegin;
            
        //Use while loop so that ret variable can be set
        while select forupdate priceChangeTrackingLoc
            where   priceChangeTrackingLoc.ChargeCodeDescription == markupAutoTable.Description
            &&      priceChangeTrackingLoc.ChargeCodeLineNum    == _markupAutoLine.LineNum
            &&      priceChangeTrackingLoc.PriceComponentCode   == markupAutoTable.PriceComponentCodeName
            &&      priceChangeTrackingLoc.FromDate             == _fromDate
            &&      priceChangeTrackingLoc.QuantityAmountFrom   == _fromQty
            &&      priceChangeTrackingLoc.ChangeType           == METPriceChangeType::AutoChargeEnabled //ie the opposite
        {
            priceChangeTrackingLoc.delete();
                
            ret = true;
        }
        
        ttscommit;
        
        return ret;
    }

    /// <summary>
    /// remove existing records to avoid duplicate processing and churn
    /// if the ONLY existing records are Disabled types then delete them
    /// </summary>
    /// <param name = "_fromDate">from date</param>
    /// <param name = "_fromQty">qty from</param>
    /// <param name = "_markupAutoLine">Markup line record</param>
    public void cleanup(FromDate _fromDate, RetailQtyLowest _fromQty, MarkupAutoLine _markupAutoLine)
    {
        METPriceChangeTracking      priceChangeTrackingLoc;
        boolean                     deleteAll = true;

        while select firstonly recid from priceChangeTrackingLoc
            where   priceChangeTrackingLoc.ChargeCodeDescription == markupAutoTable.Description
            &&      priceChangeTrackingLoc.ChargeCodeLineNum    == _markupAutoLine.LineNum
            &&      priceChangeTrackingLoc.PriceComponentCode   == markupAutoTable.PriceComponentCodeName
            &&      priceChangeTrackingLoc.FromDate             == _fromDate
            &&      priceChangeTrackingLoc.QuantityAmountFrom   == _fromQty
            &&      priceChangeTrackingLoc.ChangeType           == METPriceChangeType::AutoChargeEnabled
        {
            deleteAll = false;    //ie at least one Enabled records exists, therefore they are not all Disabled
        }

        if(deleteAll)
        {
            ttsbegin;
        
            delete_from priceChangeTrackingLoc
                where   priceChangeTrackingLoc.ChargeCodeDescription == markupAutoTable.Description
                &&      priceChangeTrackingLoc.ChargeCodeLineNum    == _markupAutoLine.LineNum
                &&      priceChangeTrackingLoc.PriceComponentCode   == markupAutoTable.PriceComponentCodeName
                &&      priceChangeTrackingLoc.FromDate             == _fromDate
                &&      priceChangeTrackingLoc.QuantityAmountFrom   == _fromQty;
    
            ttscommit;
        }
    }
